def transform(grid):
    h, w = len(grid), len(grid[0])

    # A full-color line separates the pattern from its mask.
    for r in range(h):
        if len(set(grid[r])) == 1:
            top = grid[:r]
            bottom = grid[r + 1:]
            return [
                [2 if top[i][j] != 0 and bottom[i][j] != 0 else 0
                 for j in range(min(len(top[i]), len(bottom[i])))]
                for i in range(min(len(top), len(bottom)))
            ]

    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            left_w = c
            right_start = c + 1
            width = min(left_w, w - right_start)
            return [
                [2 if grid[r][j] != 0 and grid[r][right_start + j] != 0 else 0
                 for j in range(width)]
                for r in range(h)
            ]

    return [[0 for _ in row] for row in grid]
